47:     private static void writeProblem(
48:             HttpServletRequest request,
49:             HttpServletResponse response,
50:             HttpStatus status,
51:             ContractErrorCode errorCode,
52:             String title,
53:             String detail) throws IOException {
54:         String correlationId = ApiProblemExceptionHandler.resolveCorrelationId(request);
